const fs=require('fs'),path=require('path'),vm=require('vm');const root=path.resolve(__dirname,'..');
const context=vm.createContext({window:{},localStorage:{getItem:()=>null,setItem(){}},console});vm.runInContext(fs.readFileSync(path.join(root,'dist/ship-catalog.js'),'utf8'),context);context.window=context;let game=fs.readFileSync(path.join(root,'dist/game.js'),'utf8');vm.runInContext(game.slice(0,game.indexOf("document.addEventListener('click'")),context);
const data=vm.runInContext('({buildings:BUILDINGS,tech:TECH_TREE,scans:SCAN_TYPES,structures:STRUCTURE_DEFS,ships:SHIPS,planetTypes:PLANET_TYPES})',context);
data.planetTypes=vm.runInNewContext(fs.readFileSync(path.join(root,'worker/planet-types.js'),'utf8')+';PLANET_TYPES');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cost=c=>Object.entries(c).filter(([,n])=>n).map(([r,n])=>n.toLocaleString('en-US')+' '+r).join(' · ')||'None';
const sections=[['planet-types','Planet types & special worlds',`<p>The current catalogue contains <strong>${data.planetTypes.length} worlds</strong>: original colonial environments, named Star Trek worlds, named Dune worlds, ten original Borg worlds and ten original Undine worlds. <a href="/planet-catalog.html">Search the complete illustrated catalogue and gameplay survey.</a></p><p>World types and artwork retain their registered reference names; a holder may choose a personal planet display name. Each named world type, including Earth, can belong to only one player per round. Dune aliases such as Rakis/Arrakis and Dan/Caladan represent the same world. Dune worlds are Legendary; Arrakis is Ultimate.</p><p>Refreshing registration preserves your assigned world. Before confirming, you have three server-counted rerolls per round. A reroll releases the previous reservation. A round reset renews registration and the allowance. Unique draft reservations prevent two players from confirming the same world.</p><p>Ordinary worlds start with 500–1,000 residents according to habitability. The original Borg and Undine worlds each start above 1,000, with individual bonuses from 0.05% to 5%. Housing starts at that world’s founding population. Each Biodome adds 50 places and base growth of one resident per tick; research and environmental modifiers multiply growth, and fractional settlers carry forward.</p><p>Special interface styles apply automatically at confirmation. Silver Registry, Unimatrix Sovereign, Fluidic Dominion, Imperial Legend, Arrakis Ascendant and Unimatrix999 Sovereign are visible only to the corresponding world holder and staff. Other standard themes remain selectable.</p><p>Unimatrix999 Homeworld is a one-per-round Signature world with 1,049 founding residents, 98% habitability, +36% environmental population growth and its own sovereign interface.</p><h3>Round-long fleet privileges</h3><p>Arrakis reduces outbound and return fleet ETA by one tick, minimum one tick. Construction and research time and printed ship base ETA remain unchanged. Earth’s owner receives all bonus salvage: 20% of the Metal, Crystal and Eonium build costs of ships destroyed on both attacker and defender sides when Earth participates. Simulations grant no resources; each report settles only once. The battle report shows the receipt and settlement status.</p><p>Arrakis, Earth, Unimatrix999 Homeworld and all twenty Borg/Undine worlds broadcast an anonymous charter announcement when confirmed. Reports name the world and its abilities while withholding the ruler and coordinates.</p><p>Ecology numbers are generated gameplay values, with lore-inspired environments for well-described worlds. They are not canonical population statistics. Sources: <a href="https://memory-alpha.fandom.com/wiki/Category:Planets" target="_blank" rel="noopener">Memory Alpha planet index</a> and <a href="https://dune.fandom.com/wiki/List_of_planets" target="_blank" rel="noopener">Dune planet list</a>.</p>`],
['start','Getting started',`<p>Starfall Command is a planetary strategy practice game. Build your economy, research new technology, manufacture ships, explore galaxies and coordinate with your alliance. Your practice round runs on this device; scans are stored centrally so players can share intelligence.</p><h3>Your first session</h3><ol><li>Open the portal and sign in with your game account.</li><li>Check <strong>Overview</strong> for resources, population, current projects and ships.</li><li>Use <strong>Mining</strong> to expand asteroid production, then improve refineries and factories in Construction.</li><li>Assign population to the activities you need and begin a research project.</li><li>Build a Wave Amplifier before attempting scans. Enable sharing under Planet Settings → Quick Actions if you want other players to see your scans.</li><li>Use the Galaxy Browser to find planets and open their shared intelligence.</li></ol><div class="notice">The planets, economy and combat are a practice simulation. A shared scan is a report from a player's practice round, not a live Planetarion universe record.</div>`],
['navigation','Portal, login & navigation',`<p>The portal is the starting point. <strong>Enter game</strong> opens your practice round after login; the manual can be read without a game login by visitors who already have access to this site.</p><p>The left menu groups Military, Foreign Affairs and Archive. Staff tools are accessed through the portal Staff control panel; the original in-game staff view can be enabled there. Admin Controlcenter combines round configuration, ticker, snapshots and confirmed reset with Planet Editor and Stats Editor as subpages. Alliance Controlcenter provides separate staff alliance editors; Multihunters provides separate access-log, shared-IP and fleet-movement review pages. Support tickets are available in-game and under portal User Profile. Development shortcuts at the top open Mining, Construction, Research, Government and Planet Settings. <strong>Leave unfolded</strong> keeps the menu groups expanded.</p><p>Archive contains <strong>the Miday array</strong>, News Log and Quests. Portal, Manual and Sign out links remain available from the game.</p><h3>Account security</h3><p>Passwords are stored as salted hashes. Login uses a secure server session; signing out ends that session. Five unsuccessful attempts temporarily lock an account for 15 minutes. Signing out does not erase your browser's practice round.</p>`],
['governments','Government lookup & production bonuses',`<p>Reference: <a href="https://game.planetarion.com/manual.pl?page=governments">Planetarion governments</a>, <a href="https://game.planetarion.com/manual.pl?page=population">Population</a> and <a href="https://game.planetarion.com/manual.pl?page=formulae">Formulae</a>.</p><div class="table-wrap"><table class="ship-stats-table"><thead><tr><th>Government</th><th>Production output bonus</th><th>Production cost discount</th></tr></thead><tbody><tr><td>Corporatism</td><td>0%</td><td>0%</td></tr><tr><td>Democracy</td><td>0%</td><td>8%</td></tr><tr><td>Nationalism</td><td>−10%</td><td>0%</td></tr><tr><td>Socialism</td><td>+20%</td><td>0%</td></tr><tr><td>Totalitarianism</td><td>−10%</td><td>6%</td></tr><tr><td>Anarchy / revolution</td><td>−20%</td><td>0%</td></tr></tbody></table></div><h3>Apply to running ship orders</h3><p>Population → Shipwrights supplies the population percentage bonus. Output uses the additive factor <code>1 + (population bonus + government bonus) / 100</code>. Starfall retains its existing factory build-point base and round multiplier; this update implements the manual’s production bonuses, not the entire Planetarion production-unit economy. Factory allocation remains attached to each numbered order.</p><p>Population and government output changes update the current order’s ETA and the next tick’s work immediately, without resetting progress or changing its paid costs. Government cost discounts apply only when placing a new order and are shown in the price preview. Cancellation refunds half of the cost actually paid.</p><h3>Government selection</h3><p>Choose a government under Population. First formation within the first 168 ticks is free. A later formation or a change starts a 72-tick revolution, using the Anarchy production penalty. Government mining, research and construction modifiers also apply to the current practice base rates. Covert ops separately uses the stealth and alert modifiers.</p>`],
['ticks','Ticks, protection & saved progress',`<p>A tick advances production, population, research, construction, shipbuilding, fleet missions and temporary alliance effects. The default tick interval is one hour; the round lasts 672 ticks and has 24 ticks of protection unless changed in Admin.</p><p>The countdown follows the configured interval. <strong>Simulate tick</strong> advances a practice tick immediately. When returning after an absence, the local clock catches up in bounded steps.</p><p>Browser saves preserve the current practice round. The central database stores scan reports and sharing preferences independently. <strong>Reset</strong> replaces the browser's round; it is not a password reset or a deletion of your game account.</p><p>Normal planet attacks are blocked while protection is active. Structure planets have their own war requirement.</p>`],
['economy','Resources, asteroids & income',`<p>Metal, Crystal and Eonium pay for development, ship production, scans and self exile. Each resource has an asteroid field, a refinery and a resource reserve.</p><h3>Income calculation</h3><p>Core Mining levels 0–4 provide respectively <strong>1,000; 3,500; 7,000; 12,500; 20,000</strong> base income for each resource. Every asteroid adds 250 per tick, and every matching refinery adds 1,100.</p><p>The base amount is multiplied by mining workforce and finance bonuses, the round income multiplier and applicable alliance effects. Each Finance Centre adds 0.5%. Your displayed resource rate reflects these factors and any enabled alliance tax.</p><h3>Mining capacity</h3><p>Heavy Cargo Transfers increases asteroid capacity. The progression is 100, 200, 300, 500, 750, 1,000, 1,250, 1,500, 2,000, 2,500, 3,000, 3,500, 4,500, 5,500, 6,500, 8,000 and 10,000 asteroids.</p><p>Planet value includes holdings such as resources, ships, buildings and asteroids; the practice score adds earned experience to that value. The game shows its current calculation in the planet and galaxy views.</p>`],
['population','Government, population & workforce',`<p>Population Management starts at level 0/5 in a new or reset round. Research it to expand the total assignable workforce pool; it is not granted automatically at maximum level.</p><p>The five workforce assignments are Mining, Research, Construction, Shipwright and Security. New and reset rounds start with all assignments at 0%. The department limits are Miners 25%, Scientists 50%, Builders 35%, Shipwrights 60% and Security 50%. The available workforce pool starts at 50% and increases by 10 percentage points for each Population Management level, up to 100%. Total assignments cannot exceed this pool. The interface shows assigned and remaining available percentages. Capacity Achievements unlock at 60%, 80% and 100%; a separate full-allocation Achievement requires 100% assigned.</p><p>Mining improves resource output. Research staffing scales research points; Construction scales construction units; Shipwright staffing scales factory production. Security is a dedicated allocation in the practice workforce model.</p><p>Population and base housing start at 500–1,000 according to the assigned planet type. Each completed Biodome adds 50 places. Every planet has positive ecological base growth, even with zero Biodomes. Ecology = (habitability + biodiversity + moisture + (100 − rockiness)) / 400. Base growth = (1 + ecology) × founding population / 1,000. Each completed Biodome adds +1 to this base rate. Total potential growth = (ecological base + Biodomes) × research multiplier × the planet growth modifier. Environment has a minimum positive multiplier of 0.01. Population Development research has five levels: +20% growth each, up to +100%. Fractional growth carries forward. At full housing, all otherwise-unused potential growth is converted into Galaxy Fund resources, even with zero Biodomes or ordinary population tax set to zero. New Biodomes add capacity, never instant residents. Every full 100 residents supplies +1 CU and +1 research point per tick, added after workforce and government modifiers. These bonuses update construction/research ETAs and are shown in Government, Construction and Research. Each resident contributes 0.001% to mining income, additively with workforce, finance and government modifiers. The income table separates core, asteroids, base refinery output, workforce, Finance Centre and population bonuses. Each refinery contributes 1,100 base units per tick; each Finance Centre adds 0.5% of core + asteroid + refinery income. Contributions are shown before government, round multipliers, alliance effects, strike penalties and tax. The total includes all those adjustments and final rounding. Damaged Biodomes lose corresponding usable housing. All five assignments start at 0%. Edit the sliders, then press <strong>Assign workforce</strong> to confirm; bonuses change only after confirmation. <strong>Reset to 0%</strong> clears the committed allocation.</p>`],
['construction','Buildings & construction',`<h3>Biodomes · Green Arks</h3><p>Population Development: Settlement Registry, Family Support, Medical Networks, Habitat Integration and Colonial Renewal cost 1,200 / 1,800 / 2,600 / 3,600 / 4,800 RP. Research quests reward CU/RP: 50/100, 100/150, 200/250, 400/400 and 800/600. Population milestones at 1,050 / 1,250 / 1,500 / 2,000 / 3,000 grant the same five reward tiers. All belong to Secretary of Development. Each achievement category has its own tab.</p><img src="/assets/biodome.svg" alt="Green Ark Biodomes on a colony" style="width:100%;max-width:720px;border-radius:8px"><p>When the jumpgates fell silent, the Green Ark programme sheltered settlers beneath radiation-shielded gardens. Each completed Biodome provides 50 places, increasing the type-dependent starting capacity. Each Biodome generates +1 resident per tick, boosted by +20% per Population Development research level (maximum +100%); construction does not instantly add people.</p><p>Base cost is 300 Metal, 200 Crystal and 100 Eonium: 600 total, one fifth of a refinery’s 3,000-resource base cost. A full Biodome adds only 0.05% income across all three resources, while a refinery adds 1,100 base units to one resource. The lower habitat price reflects its slower indirect return. Normal construction price escalation and shared facility limits apply. Construction work: 250 CU.</p><p>Structure killers can damage Biodomes after the ship battle. Each dome has 1,000 HP. Damage is applied sequentially; 20 damage removes one of its 50 resident places. A destroyed fully occupied dome loses 50 residents; a half-damaged one loses 25. Previous damage is retained, so another attack only charges new damage. Casualties cannot exceed remaining population.</p><p>Construction spends resources and progresses through construction units. One active order can be accompanied by queued orders. The game shows the remaining work and estimated ticks; cancel controls describe the refund available for that order.</p><p>Construction output is based on staffing: a 20% construction allocation provides 100 construction units per tick. Building costs and capacity may change with development, so the order card is the authoritative price before purchase.</p><div class="table-wrap"><table><thead><tr><th>Building</th><th>Purpose</th><th>Base resource cost</th><th>Work</th></tr></thead><tbody>${Object.entries(data.buildings).map(([id,b])=>`<tr><td><span class="manual-building-name"><img src="/assets/structures/${id}.svg" width="64" height="26" style="object-fit:cover;border-radius:4px" alt="${esc(b.name)} illustration">${esc(b.name)}</span></td><td>${esc(b.desc)}</td><td>${esc(cost(b.cost))}</td><td>${b.cu} CU</td></tr>`).join('')}</tbody></table></div>`],
['research','Research branches & progression',`<p>Research has four slots in total: one active project and up to three waiting projects. You can queue the next branch level while research is running. Each tick adds points to the active level, then the next waiting project starts. The branch card shows the next unlock, progress and approximate duration.</p><p>Research output starts from the race base: Terran 95, Cathaar 110, Xandathrii 105, Zikonian 95 and Eitraides 100 RP. Scientist assignment, government and laboratory-density percentages add together; laboratory density is capped at 20%. The round multiplier and the additional RP per full 100 residents then apply. The displayed rate reflects these Starfall modifiers.</p>${data.tech.map(t=>`<details><summary>${esc(t.name)} · ${t.max} levels</summary><p>${esc(t.desc)}</p><ol>${t.levels.map(level=>'<li>'+esc(level)+'</li>').join('')}</ol></details>`).join('')}`],
['ships','Factories, ship production & fleets',`<p>Production lists the ships for your planet's race. An order requires the matching hull research, the correct factory and enough resources. Enter a quantity to see the total cost before ordering.</p><p>Light factories build Fighters and Corvettes. Medium factories serve Frigates and Destroyers; Heavy factories build Cruisers and Battleships. Assign owned factories to production to make use of their throughput. Queue and cancel controls manage ongoing orders.</p><p>Autofill buttons calculate the ships needed to reach a target fleet total, rather than ordering that many additional ships.</p><h3>Fleet management</h3><p>Your ships occupy Base, personal Fleet 1–3 and the permanent fourth Alliance Fleet. Transfer ships into a field fleet before launching a mission. Launching removes those ships from the ready fleet and creates an outbound mission. Recall controls send active missions home.</p><p>Out-of-galaxy travel starts at 12 ticks for Fighters and Corvettes, plus one for Frigates and Destroyers or two for Cruisers and Battleships. Space Travel removes up to four ticks. Same-alliance defence removes one more; in-galaxy defence takes five ticks. The practice Transwarp Hub can reduce out-of-galaxy travel by one.</p><h3>Ship roster</h3><p>Every race has a distinct roster and artwork. Production cards expose targeting, initiative, guns, damage, armour, role, cloak, ETA and cost. Use those current cards and the battle calculator when composing a fleet.</p>`],
['combat','Combat, targeting & defence',`<h3>Population and habitats in battle</h3><p>Pop dmg% is an editable ship stat for Cruisers and Battleships. Its default is 0.1% of the defender’s starting population per surviving ship after the ship battle. Percentages add together, capped at 100%; final casualties are rounded down. Their original ship targets remain active; other classes have a blank population damage field. The battle calculator accepts defender residents, Biodome count and existing dome damage. Reports show population casualties, survivors, remaining mining bonus, destroyed domes and partial damage. Civilian losses also reduce the +1 CU/RP per full 100-person production bonus.</p><p>Attack, defence and related fleet operations use the practice combat resolver. Ship class targeting, initiative, damage and armour determine how engagements unfold. Cloaked units and specialised roles may affect what reports show.</p><p>Planet protection blocks ordinary attacks until the protection period ends. Hostile alliance structure planets require a declared war with their owner before they can be attacked.</p><p>Base fleet behaviour can be set to Stay Home and Fight or Run and Hide. Alliance defence calls identify a planet, hostile ETA and notes; select a ready fleet to respond.</p><h3>Battle calculator</h3><p>Under Alliance, paste ship reports into the attacker or defender side, parse their counts and calculate. The result shows starting fleets, losses and survivors. You can also copy counts and results. A calculator result is a practice estimate rather than a guarantee of a live game's outcome.</p>`],
['scans','Waves & scan types',`<p>A Wave Amplifier is required to scan. The first amplifier enables scanning; each additional amplifier reduces costs by 0.3%, capped at a 75% discount. Each listed base cost is paid in <strong>each of Metal, Crystal and Eonium</strong>.</p><p>Use the X:Y:Z fields, or enter compact Galaxy:slot coordinates. <code>2:7</code> selects galaxy 2, planet slot 7 in your home sector; <code>07:04:02</code> is the full form. Paste one coordinate into the paste box, apply it, then choose a scan type to launch.</p><div class="table-wrap"><table><thead><tr><th>Scan</th><th>Scan research level</th><th>Base cost each</th><th>Information</th></tr></thead><tbody>${data.scans.map(([id,name,amount,desc],i)=>`<tr><td>${esc(name)}</td><td>${i}</td><td>${amount.toLocaleString('en-US')}</td><td>${esc(desc)}</td></tr>`).join('')}</tbody></table></div><p>Landing Scans require a fleet at ETA 1. Incoming Scans require an inbound enemy fleet. The scan cards show the research needed, current cost and whether the action is available.</p><p>The appointed scanner, an Alliance Scanner or the Alliance HC can use the available funding controls. Galaxy sweeps require the appropriate scanner or Minister of War permission. Each target/type pair must meet the same requirements as a single scan; ineligible pairs are skipped before the total bill is calculated. Incoming scans report hostile movements toward your own planet and occur at most once in a sweep. Jumpgate probes report travelling fleets, not docked ships. Missing fleet composition or guard intelligence is shown as unknown. These permissions remain separate from the option to share reports with everyone.</p>`],
['miday','the Miday array & central sharing',`<p><strong>Archive → the Miday array</strong> is the central scan archive. Every report has an icon identifying its scan type, target, tick and saved time. Reports remain available for two weeks.</p><h3>Store privately or share with all players</h3><ol><li>Open Planet Settings.</li><li>Under Quick Actions, find <strong>Enable sharing of scans to all people</strong>.</li><li>Enable it to make your centrally stored scans visible to other game visitors.</li><li>Disable it to hide your scans from the shared archive. The central copies remain private.</li></ol><p>Sharing starts disabled. Your sign-in identifies the owner of your reports; another player cannot overwrite or delete them. Deleting a saved scan also removes its central copy.</p><h3>Search and type filters</h3><p>Search by planet name, coordinates, scan name or words from the report. Each scantype checkbox can be switched on or off, just like news categories. All scan types enables or disables the complete set. Use Refresh Scans for the latest records and Load More Scans when more results are available.</p><h3>Scans for one planet</h3><p>The archive button next to P, D, A and U in Galaxy Browser opens all shared scans for that planet, with all types selected. Clear Planet Filter returns to the wider archive.</p><h3>Anonymous reports</h3><p>An anonymous report hides its coordinate field and coordinate strings in the shared report text. Anonymous scans are excluded from coordinate-based planet lookups. Their type and target name remain visible.</p><p>Everyone means everyone who can access this Site and sign into the game. The site's existing access policy is not changed by scan sharing.</p>`],
['galaxies','Galaxies, slots & self exile',`<p>Galaxy Browser accepts X:Y coordinates and shows tracked practice planets or deterministic simulated galaxies. Every galaxy displays exactly <strong>15 slots</strong>: 1–10 are planet slots and 11–15 are reserved for alliance stronghold structures.</p><p>Empty structure slots display <strong>Empty / Reserved</strong>, even where no stronghold exists. Structure rows have their own labels, and an occupied planet slot is never used for a stronghold structure.</p><h3>Exile Option</h3><p>Planet Settings replaces Layout Module with Exile Option. Yes is unchecked by default. Checking it shows confirmation and the exact resource charge before your planet moves to a free slot in a different galaxy. All fleets must be home and you must be able to pay.</p><p>The charge is shown separately for each resource. It rises with your previous self-exile count and your galaxy's counted score relative to the average. Free planets pay twice the paid-planet cost. This game uses tracked local galaxy scores to apply the <a href="https://game.planetarion.com/manual.pl?page=formulae" target="_blank" rel="noopener">Planetarion self-exile formula</a>.</p><p>Payment goes into the galaxy fund of the galaxy you leave. Your fleet, buildings, research and alliance membership remain. The practice relocation is immediate, rather than waiting for one of the next four ticks as in Planetarion.</p><p>Counted score records progress gained in the current galaxy. Score brought in through exile does not count as newly earned galaxy score.</p>`],
['alliance','Alliances, funds & strongholds',`<h3>Diplomacy and Mail</h3><p>Foreign Affairs → Mail provides a private inbox, sent folder, player recipient list, reply and 20-message pagination. Only the sender and recipient can read a message; admin status grants no mailbox bypass.</p><p>War and peace declarations notify both alliances through their News Log. The target’s current players also receive Mail. Reports name the declaring and target alliances, include a clearly fictional diplomatic transcript, and show applicable bonuses.</p><p>Following the <a href="https://game.planetarion.com/manual.pl?page=alliance">Planetarion alliance manual</a>, attacks on a declared target gain 5 capture percentage points and 25% asteroid-capture XP if you are the only declarer or the target has a higher aggregate score. Otherwise the bonuses are 3 points and 15%. During an active war, other targets receive a 5-point capture penalty and 25% capture-XP penalty. War bonus lasts 48 ticks. Wars unlock after the universe shuffle and require at least five planets in each participating alliance. Only one primary war may be active. The declaration may include the target’s allies, who receive the secondary 3-point / 15% bonuses. Allied status requires a proposal accepted by the other alliance; either party may end that treaty when not at war. Bonuses affect actual asteroid capture and capture XP. Capturing from an undefended planet earns XP; ship losses alone do not. A war mandate cannot be cancelled before its 48-tick expiry. Expiry withdraws the sender’s declaration and does not silently cancel a separate declaration by the other side.</p><h3>Private alliance intelligence</h3><p>Nicknames, assessed alliance affiliations, notes and relations are separate records for each alliance. They are not inferred from another alliance or filled from public player usernames. Membership and rank determine access; scans explicitly shared to all remain available according to their sharing setting.</p><h3>Admin key audit</h3><p>Owner keys may be revealed with a holder passphrase or by an admin force reveal. Every successful reveal records admin, alliance, keyholder, action and timestamp. The audit never includes the key or passphrase. Displayed keys hide after 60 seconds.</p><p>Alliance pages cover members, recruitment, defence calls, the battle calculator, alliance funds, fortress placement, structures, relations and logs. Owner and HC manage fortress placement, roles and structures according to rank permissions.</p><p>Accepted applicants begin as Recruits. Members can hold Member, Scanner or Officer roles; Owner is the highest rank; Owner changes are restricted to Owners and authorised staff. The alliance supports up to 40 members.</p><h3>Create or recover an alliance</h3><p>Open Alliance and enter a unique name, tag, description, recruitment message and MOTD. The creator becomes Owner and receives a personal encrypted passkey. No practice planets are automatically created in the player-only round.</p><p>When you have no alliance, the Restore an alliance box remains visible even while ticks are running. Enter your personal Owner passkey to recover a reserved alliance name and its saved attributes. Joining or restoring an alliance hides the box. Recovery does not restore funds, structures, scans or intel.</p><p>User control panel → Alliance manager supports five inactive reservations and up to two additional keyholders. Only an Owner or authorised staff can grant or remove Owner rank.</p><h3>Alliance Intel</h3><p>Alliance Intel has a separate browser of existing galaxies, occupied slots, planet and note search, and a dossier for every populated slot. Assess planets as Friendly, Watch or Hostile and save a note. Reports combine your own saved scans with centrally shared reports for those coordinates. Notes and assessments are saved with this device’s practice alliance. Ranks controls who may view intel and edit assessments.</p><h3>Ranks and permissions</h3><p>The Ranks tab controls every alliance option for HC, Officer, Scanner, Member and Recruit. By default Members may exchange fund reserves, while only HC can configure minimum reserves and permissions. Each fund exchange must leave all three resulting reserves at or above their configured minimum. The player or game admin with permission access can save a custom role matrix or restore defaults.</p><h3>Funds and taxes</h3><p>Donate to Alliance Fund deducts a positive whole amount from your planet and schedules it to arrive after 8 ticks. Combined donations of each resource are capped at two ticks of income per 24 hours. Exchange Resources converts personal reserves, or alliance reserves according to rank permissions, with a 2.5% fee rounded up to a whole resource unit. For example, giving 1,000 Metal receives 975 Crystal. The result stays in the selected account.</p><p>Alliance tax is configurable from 0% to 5%; a planet can enable or disable its contribution in Planet Settings. Donations are limited and scheduled rather than credited immediately. Galaxy Fund is separate and has its own permissions and donation controls.</p><h3>Fortress benefits</h3><p>Only alliance members residing in the stronghold galaxy receive the fortress's <strong>0.25% passive resource bonus</strong> and its free Wave Distorter every 24 hours. Moving the fortress after the first tick starts a 24-hour anarchy period, with an alliance-wide 2% income penalty.</p><p>A stronghold must be placed in a galaxy that contains alliance members. Its structures occupy standard slots 11–15; an active 1:1 stronghold uses slots 16–20.</p>${Object.entries(data.structures).map(([id,d])=>`<details><summary>${structureIcon(id)}${esc(d.name)}</summary><p>${esc(d.desc)}</p><p>Cost: ${Math.round(d.share*100)}% of calculated daily alliance tax income. ${d.cooldown?'Cooldown: '+d.cooldown+' ticks.':'Repeatable.'}</p></details>`).join('')}<p>Active structures expire according to their displayed tick or hour duration. The five-amplifier and five-distorter megastructure rewards retain their alliance-wide scope; those differ from the fortress's location-specific daily reward.</p>`],
['politics','Politics & galaxy governance',`<h3>Population levy and Spaceport</h3><p>The Minister of Development sets ordinary population tax to 0–5 residents per planet per 24 ticks. Collection accrues fractionally and removes whole residents, with a hard maximum of five actual residents per planet in any rolling 24-tick window. At zero, ordinary collection pauses. When verified housing is full, otherwise-lost potential growth is converted in full, even when ordinary tax is zero; this does not remove existing residents. Fractional growth equivalents carry forward. Each removed resident or converted whole growth equivalent yields 6 Metal, 4 Crystal and 2 Eonium for the Galaxy Fund. The Civil Population register shows ordinary removals, full-housing conversion, projected next-tick income and actual reports separately. Only a planet’s own advanced tick reports are settled; missing historical ticks are identified rather than estimated. Legacy percentage liabilities are discarded when adopting this policy. Shared reserves appear under Spaceport, and only the Economics Minister can issue eligible aid payouts.</p><p>Galaxy politics handles commander votes, minister appointments, a message and banner, trust policies, fund permissions and exile votes. Minister roles cover Communication, Development, War, Economics and scanning.</p><p>Galaxy exile votes are different from voluntary self exile. They require funding and minister approvals, and the practice system limits them to two in a 200-tick window. Review the target, reason and displayed cost before opening a vote.</p><p>Voluntary self exile moves you into another galaxy and resets the local political context and galaxy-fund view to your new location. Alliance membership is preserved.</p>`],
['archive','News, quests & troubleshooting',`<h3>Biodome quest line</h3><p>Habitat milestones at 1/5/15/25/50 completed Biodomes reward respectively 50/150/300/500/1,000 CU and 50/100/200/350/700 research units (RU, shown as RP in the bank). Each objective pays once and grants no resource or asteroid rewards. Total CU is 16% of the base work for 50 Biodomes.</p><p>News Log records events from your practice round. Category checkboxes switch Economy, Development, Research, Fleet, Intelligence, Alliance, Politics and System events on or off. The search field narrows the visible messages.</p><p>Quests track supported local objectives. Completed quests can be claimed once per round for 500 Metal, 350 Crystal and 200 Eonium. Off-site objectives are marked unavailable.</p><details><summary>Why is a scan unavailable?</summary><p>Check that you have a Wave Amplifier, the required scan research, an existing target at the selected coordinates, the necessary special fleet condition and enough resources in the selected funding source. Alliance Scans must be enabled to launch scans.</p></details><details><summary>Why is the Miday array empty?</summary><p>No matching player may have enabled sharing, or your filters may exclude the results. Enable all types, clear the planet filter and search text, then refresh. New databases begin empty; preview example reports are never published.</p></details><details><summary>Why did sharing fail?</summary><p>Confirm you are signed in and your connection is working. The page shows database errors instead of reporting a successful save. Refresh Scans reconnects to the central service.</p></details><details><summary>Why does a galaxy show Empty / Reserved?</summary><p>Those slots are reserved for stronghold structures, whether or not that galaxy currently contains a stronghold. They are not extra planet slots.</p></details><details><summary>Can I edit the practice round?</summary><p>Administration includes round configuration, planet editing, ship statistics and JSON snapshot tools. Export a snapshot before major changes. Those tools affect your browser's simulated round and do not turn practice planets into live multiplayer planets.</p></details>`],
];
sections.push(['havoc','Administration & Havoc', '<p>Round setup configures the local round. Planet tools can unlock every research branch or add one of each construction to your current planet.</p><h3>Havoc control board</h3><p>Configure research levels, construction counts, resources, asteroids, base-fleet totals per class and minutes per tick. Apply to all immediately sets those values on every saved practice planet. Smaller tick intervals make the game faster. Class totals are distributed across each race’s ship types; active missions retain their fleets.</p><p>Reset to previous restores the state from before the most recent Havoc application, including resources, asteroids, fleets and gamespeed. The backup survives page reloads. It is a single-step undo.</p><h3>Dummy alliance members</h3><p>Signed-in game admins can select an unassigned dummy in Alliance → Members and add it to the alliance, or create a new dummy member. High Commander rank alone does not show this admin control. Administration → Planets also offers the alliance selector and Add Dummy Member.</p>'], ['lore','The Vesper Chronicles','<p>When the Starfall collapsed the old jumpgate network, five civilisations found themselves stranded around the Vesper Reach. Terran shipyards rebuilt the trade routes. Cathaar listening posts followed signals through the dust. Xandathrii navigators mapped the silent corridors, while Zikonian foundries and Eitraides archives preserved the tools needed to survive.</p><p>The eleven command offices issued a shared charter: restore the mines, protect the colonies, and uncover the last transmission of the Miday beacon. No fleet has yet reached its source. Every commander who rebuilds a world brings the Reach one jump closer.</p>']);
function structureIcon(id){return vm.runInContext('structureGlyph('+JSON.stringify(id)+')',context);}
const categoryIcons={governments:'POLITICS',start:'SYSTEM',navigation:'SYSTEM',ticks:'SYSTEM',economy:'ECONOMY',population:'POLITICS',construction:'DEVELOPMENT',research:'RESEARCH',ships:'FLEET',combat:'FLEET',scans:'INTELLIGENCE',miday:'INTELLIGENCE',galaxies:'SYSTEM',alliance:'ALLIANCE',politics:'POLITICS',archive:'INTELLIGENCE',havoc:'DEVELOPMENT',lore:'SYSTEM'};
sections.push(['covert','Covert operations',`<h3>Quiet Picket · Worker Bribery</h3><p>Covert couriers entice organisers with hardship credits and promises of better contracts. At covert level 3, send at least 10 agents. Success starts a non-stacking 6-tick workers’ strike, reducing mining income by 10% without killing residents. Existing strikes cannot be renewed until they end.</p><h3>Glassfall · Biodome Sabotage</h3><p>At covert level 6, send at least 15 agents to a planet with a known Biodome. Each 15 agents destroys one Biodome, bounded by actual buildings. Destruction costs up to 50 occupants per dome, subtracting casualties already caused by partial damage. Research, agents, stealth, protection and mission costs follow the covert rules.</p><h3>Civil covert quest lines</h3><p>Separate lines for successful worker bribery and Biodome sabotage award once at 1, 5 and 15 operations. Each milestone grants 100/200/400 CU and 200/400/800 RU. Failed and ineligible operations do not advance these lines. Rewards are held in the existing bonus bank.</p><h3>Military command</h3><p>Open Military → Covert ops to train or dismiss agents and guards, select a practice target, choose an unlocked operation and send agents. Results are instantaneous and appear in the blue Covert ops news category.</p><h3>Research and launch checks</h3><p>The existing covert research branch unlocks nine operations. Protection, paused ticks, closed targets, insufficient agents, insufficient resources and exhausted stealth prevent launch. Mission cost is 500 of each resource per agent, also on failure.</p><h3>Scope and rates</h3><p>Target changes affect this browser’s practice snapshot; this is not a server-authoritative multiplayer attack system. Training and wages are explicitly shown as Starfall practice rates. Mission rules are based on the <a href="https://game.planetarion.com/manual.pl?page=covertops">Planetarion covert manual</a>.</p><h3>Bonuses</h3><p>Quests → Bonuses shows current unused resources, asteroids, RP and CU. The startup grant is imported once: 2,000,000 per resource plus 7,000 CU and 8,000 RP adjusted for race. Historical loyalty defaults to zero because previous-round history is unavailable. <a href="https://game.planetarion.com/manual.pl?page=formulae">Startup rules</a>.</p>`]);
const manualSteps=items=>'<div class="manual-flow">'+items.map(([number,title,text])=>'<article><span class="manual-step-number">'+number+'</span><h3>'+title+'</h3><p>'+text+'</p></article>').join('')+'</div>';
sections.push(['order-drafts','Draft orders: ships & asteroids','<p>Ship Production and Mining share the same two-stage ordering workflow. Drafts persist in the browser and do not charge resources.</p>'+manualSteps([['01','Choose an amount','Enter the number of ships or asteroids. For ships, choose Base or Fleet 1–3 as the delivery destination.'],['02','Add to order','Build a draft from several ship types or resource types. Remove entries or clear the draft before confirming.'],['03','Order all','The whole bill is checked against resources, research and capacity. Failure preserves the draft without partial payment.'],['04','Delivery','Ships arrive in their selected fleet on completion. Asteroids are initiated immediately using their current rising prices.']])+'<h3>Independent orders</h3><p>Order now remains available on every card. Ship orders still use one active and one queued order; asteroid orders retain mining capacity limits.</p>']);
sections.push(['bonuses','Quest rewards, medals & bonus allocation','<p>Each supported quest shows its lore, exact reward and progress before completion. A completion medal marks a reached goal; claiming upgrades it to gold. Every quest is claimable once per round. Planet Settings has an opt-in Quest automation control that claims completed rewards into the bank; allocation remains manual. Claim all completed is available for each category and at the end of the board; it only collects reached, unclaimed goals.</p>'+manualSteps([['01','Complete the charter','Meet the displayed objective. Unsupported objectives are explicitly marked unavailable.'],['02','Claim the reward','The reward enters the unused bonus bank; it is not silently applied.'],['03','Open Bonuses','The Bonuses tab is alongside Quest board, using the same tab layout as Alliance.'],['04','Allocate','Accept resources/asteroids or allocate whole RP/CU amounts to branches and buildings. Partial progress and unused points persist.']])+'<h3>Startup grant</h3><p>A one-time startup grant supplies 2,000,000 of each resource. Its RP/CU totals depend on the race at import. No previous-round loyalty bonus is invented.</p><div class="table-wrap"><table class="table"><thead><tr><th>Race</th><th>Research points</th><th>Construction units</th></tr></thead><tbody><tr><td>Terran</td><td>7,600</td><td>8,750</td></tr><tr><td>Cathaar</td><td>8,800</td><td>7,350</td></tr><tr><td>Xandathrii</td><td>8,400</td><td>7,000</td></tr><tr><td>Zikonian</td><td>7,600</td><td>8,050</td></tr><tr><td>Eitraides</td><td>8,000</td><td>7,700</td></tr></tbody></table></div><p><a href="https://game.planetarion.com/manual.pl?page=formulae">Startup formula</a> · <a href="https://game.planetarion.com/manual.pl?page=races">Race adjustments</a></p><h3>Temporal command quests</h3><p>The first manual start, first stop and first restart each unlock one asteroid of every type. Their lore appears on the board; claim and accept through Bonuses. Scheduled starts award no quest progress.</p>']);
sections.push(['ticker','Ticker, clocks & scheduled starts','<p>Staff control panel → Admin Controlcenter → Round &amp; ticker contains the ticker controls. A new or reset game starts with the ticker stopped and the old scheduled start cleared. Start it manually or save a new future start time. This is a browser-practice ticker: it runs while the game is open and catches up at most 24 ticks after inactivity.</p>'+manualSteps([['▶','Start / restart','A fresh interval is scheduled. A manual action can unlock the first-start or first-restart quest once.'],['Ⅱ','Pause','Automatic ticks freeze and interval progress stays still. Run one tick is an explicit manual action.'],['■','Stop','Stops automatic ticks and resets the displayed interval bar. The first stop has a one-time quest reward.'],['◷','Schedule','Choose a future local date/time and save. The game must be open when processing the schedule; automatically starting never unlocks ticker quests.']])+'<h3>Time information</h3><p>The header shows current tick, next-tick countdown, an interval progress bar, a local 24-hour clock and synchronized server UTC. Page load measures browser navigation time; Server RTT measures the full network round trip. These clocks do not mean the simulation runs as a server-authoritative ticker.</p><h3>Game updates</h3><p>Starts, pauses and stops confirm with a toast and prominent yellow/black entries in Recent signals and News Log. Toggle the Game updates category in the news filters.</p>']);
sections.push(['staff-news','Staff tools & publishing news','<p>The portal Staff panel is restricted to game admins. Tabs separate round tools, user assignments, news articles and reset.</p>'+manualSteps([['01','Compose','Choose one of five update categories, enter a title, synopsis and article text. Font controls format selected text.'],['02','Publish','Publishing creates a central database article and a permanent article link.'],['03','Edit / save','The staff-made article list sits below the editor. Edit loads the article and exposes Save changes; saving updates the same entry.'],['24h','Pinned news','New staff articles join portal News posts and the archive. For 24 hours a pin badge and highlighted border keep them prominent; afterwards their normal layout and date order return.']])+'<h3>Category colors</h3><div class="manual-category-key"><span style="--key:#caa0ff">Game mechanics</span><span style="--key:#85caff">Round update</span><span style="--key:#83dfa3">Stats update</span><span style="--key:#ff939c">Error update</span><span style="--key:#ffe279">Pause / resume</span></div><h3>Reset</h3><p>The confirmed round reset recreates planets and alliances and clears intel, scans, quests, rewards and game news. All buildings and research reset to zero. Tax and sharing preferences reset unchecked. The Leave unfolded menu preference is retained as an interface setting. Accounts and passwords remain.</p>']);
sections.push(['races','Races & bonuses','<p>Compare civilisations, fleet doctrine and bonus reference values. Applied startup bonuses are marked separately.</p><div id="manualRaceEncyclopedia"></div><p><a href="/#race-encyclopedia">Back to the portal race encyclopedia →</a></p>']);
sections.push(['alliance-ownership','Alliance ownership & recovery','<h3>Owner rank</h3><p>Alliance creators become Owners. Only an Owner or staff can grant or remove Owner rank; the last Owner must appoint a successor before stepping down.</p><h3>Alliance Settings</h3><p>Edit the name, description, recruitment message and MOTD in separate boxes. Owners each see only their own personal passkey.</p><h3>Passkey recovery & feeds</h3><p>Reserved alliance names require a valid Owner passkey to recreate. Configuration survives resets; funds, structures, scans and intel remain reset. The private feed applies the current Owner intel permissions.</p><pre><code>Authorization: Bearer &lt;your personal Owner passkey&gt;</code></pre>']);
sections.push(['attack-operations','Alliance attack tool & fleet worksheet','<h3>Operations and shared wave bookings</h3><p>Alliance → Attack tool now follows the pa-tools planner model. Owner, HC and Officer manage operations by default; every rank except Recruit can claim waves by default. Create up to 50 registered targets and 1–10 consecutive landing waves, with optional scheduled opening and prerelease. Targets sort numerically by coordinates. Each target/wave has one owner and may be shared with current alliance members. Shared participants can edit notes, calculator references and NONE/LAND/RECALL planning status. The owner must transfer a shared booking before dropping it. Status changes do not launch or recall real fleets; use Fleets or Alliance Launch Bay for orders. The My bookings filter includes owned and shared bookings.</p><p>Managers can add or remove unclaimed waves and targets. Claimed waves cannot be removed or retimed until released. Revision checks protect simultaneous claims. Scheduled target details are hidden from ordinary members until prerelease; all records remain scoped to the alliance and round generation. Previous open targets and claims are imported once. The old claim endpoint becomes read-only after the upgrade. Alliance → Battlegroups provides membership requests, approvals and command transfer.</p><p>Adapted for Starfall from <a href="https://bitbucket.org/liamrigg/pa-tools" target="_blank" rel="noopener">liamrigg/pa-tools</a>, reference commit 564f02157c7c028beb57c16b4c8a2c02869b35ba. The planner runs in the Starfall Worker, with no external bot notifications.</p><p>Battle calculator offers a compact worksheet: each ship occupies one row with Attacker and Defender count cells. Ship class colours match the legend. Use Tab or arrow keys to navigate. Paste tab-separated numeric columns from a spreadsheet starting at a selected cell: the first column maps to Attacker and the second to Defender. Values must be whole numbers from 0 to 1,000,000,000. Fighters are cyan, Corvettes green, Frigates yellow, Destroyers orange, Cruisers purple and Battleships pink. Reports are simulated and remain on the calculator page.</p>']);
sections.push(['community-support','Forums & support tickets','<h3>Forums</h3><p>Alliance → Alliance Forums opens the members-only discussion area. Creating a topic or posting a reply advances the Post in your alliance forum achievement; only your own posts in the current alliance count. Galaxy Forum is limited to planets in your own galaxy and advances the Post in the galaxy forum achievement. The in-game Forums menu also includes General forum for all signed-in players, alongside My galaxy forum and My alliance forum when available. General topics support posts and replies. Alliance topics are visible only to members of that alliance. Private alliance and galaxy discussions are cleared by a round reset; community topics remain.</p><h3>Support tickets</h3><p>User Profile → Support tickets offers Staff support and Ban appeal. Only the requester and staff can read a ticket. Staff can reply and mark requests Open, In progress or Resolved.</p><h3>Ambient soundtrack</h3><p>The portal offers an original cinematic desert-space score with mute and volume controls under User Profile → Portal theme settings. Browsers may require a click before playback. Music pauses while a portal video plays. In-game music starts disabled; enable it under Planet Settings → Ambient soundtrack.</p><h3>Theme preferences</h3><p>Alternate portal themes on every reload cycles all seven portal themes, including Neutral. A fixed selection disables cycling. User Profile → Portal theme settings controls the portal and manual theme. Remember setting saves the choice in this browser; theme changes reload the page. Game theme controls remain under Planet Settings.</p><h3>Staff account audit</h3><p>Multihunters → Raw access log shows signed-in request metadata and account IP history. Multi groups accounts sharing an observed IP. Only staff can view this data; records expire after 30 days. Shared networks alone do not establish account ownership. Keyholders can authorise staff disclosure of their alliance key with a personal passphrase; rotating the key clears the previous phrase.</p><h3>Alliance creation & keyholders</h3><p>Create alliance accepts name, tag, description, recruitment message and MOTD. The creator becomes Owner and receives an encrypted personal passkey. An optional 12–128 character passphrase enables staff disclosure for that specific Owner key; leave empty to disable disclosure. Alliance Controlcenter → Keyholders lists all alliances, including archived key registrations, independently of the alliance selector. The same account can hold separate keys for different alliances. Revealing a key requires its matching alliance and holder. The normal action uses an authorised passphrase; game admins also have a Force reveal action. Every successful reveal is logged with admin, holder, alliance, action and timestamp, without the key or passphrase. Rotation invalidates the old phrase.</p><h3>User and Staff control panels</h3><p>The User control panel has a single submenu for Account profile, Portal theme settings, Alliance manager, Support tickets and Create account. Alliance manager permits five pending reservations, with encrypted personal keys and up to two additional holders. Reservations do not change the current round alliance until explicitly activated. Active alliance holders must already be members and become Owners.</p><p>Staff account ranks are Player, Support, Multihunter and Administrator. Support handles tickets; Multihunter handles access and fleet review; Administrators manage accounts and game settings. Staff planet audit is readable by all staff roles and lists recorded field changes. It begins recording with this release and cannot reconstruct past field edits. Game and staff workspaces use separate browser saves.</p><p>The player-only round contains account-owned planets; automatically generated practice planets are disabled. Resets preserve this mode and keep the ticker stopped until manually started or scheduled anew. The practice schedule processes while an appropriate page is open.</p><h3>Staff workspaces</h3><p>Administration now lives under Portal → Staff panel. Admin Controlcenter, Alliance Controlcenter, Multihunters and Support tickets have dedicated subpages. Staff can continue playing their own assigned planet. The staff workspace saves separately in this browser and does not automatically advance gameplay ticks. Staff overview has a toggle and link to restore the original ingame Administration view.</p><h3>Staff structures & battle lab</h3><p>Alliance Controlcenter → Structures displays five reserved slots and construction progress. Staff generation queues a three-tick build without charging the alliance fund, or immediately activates a timed structure. Satelite Uplink → Simulated battle lab generates local test combat reports, can load the starting fleets into Battle calculator. Test reports are labelled simulated, stay in their test module and do not change real assets or farming evidence. Calculator news reports stay on the calculator page.</p><h3>Multihunter fleet analysis</h3><p>Staff can open Administration → Multihunters → Fleet farming analysis and select two planets and a tick range. The report lists both directions, attacks, completed battle reports, asteroid captures, losses and repeated launch intervals. At least four attacks and three profitable low-loss battles recommend staff review. Fewer than three completed attack reports produce Insufficient evidence. Events are authenticated account reports from the practice browser, not authoritative server combat evidence. Collection begins with this release; no historical movements are invented. Round generations are kept separate. The analysis never bans a player or proves collusion.</p><h3>Multimedia & Discord</h3><p>The portal contains an interface montage and AI battle concept clips with an original cinematic soundtrack: three 24-second battles and an 80-second montage. Discord chat currently contains YouSMP configuration placeholders until an authorised embed is available.</p>']);
sections.push(['fleet-operations','Fleet operations & vendor sales','<h3>Themes &amp; calculator</h3><p>Classic is an old-school in-game skin under Planet Settings. Nyan Cat is a portal/manual arcade theme under User Profile and joins theme cycling. Fleets → Add to Calc loads the selected ready and deployed fleet as attacker, preserves defender inputs and opens the battle calculator.</p><h3>Network Hub</h3><p>Network Hub replaces Galaxy Status. Incoming, outgoing and returning fleets are separate tables. Enable alliance intel adds permitted alliance threat reports and assessments. Unknown counts and origins remain unknown.</p><h3>Personalised fleets</h3><p>Fleets → Personalised fleet names accepts three distinct names of 3–15 letters or numbers. Internal fleet slots remain unchanged.</p><h3>Scheduled launches</h3><p>Set a delay of 0–12 ticks before launching. Ships are reserved immediately and depart when the practice ticker reaches that tick. Cancelling before departure returns them immediately. This browser practice ticker must be running or catch up for the schedule to execute.</p><h3>Fake Defence</h3><p>Fake Defence recalls automatically when travel reaches ETA 1, before arrival. It returns over the travelled distance.</p><h3>Ship Analysis</h3><p>The table totals normal damage, EMP shots and stealing damage against primary target classes across ready and deployed ships. Enemy resistance, initiative and target priority affect actual combat; use the battle calculator for a battle estimate.</p><h3>Vendor sales</h3><p>Production → Sell ships removes ships from the Base fleet for 12 ticks. The practice vendor pays a displayed fixed 50% of catalog resource cost; this rate is a Starfall rule. Cancelling returns the ships after a new 12-tick trip. Ships with the vendor remain included in planet value.</p><p>Reference: <a href="https://game.planetarion.com/manual.pl?page=fleets">Planetarion Fleets</a> and <a href="https://game.planetarion.com/manual.pl?page=production">Production</a>.</p>']);
sections.push(['launch-bay','Alliance Launch Bay & fleet readiness','<h3>Permanent fourth fleet</h3><p>The fleet system now has Base, three personal fleets and a fourth deployable Alliance Fleet. Transfer ships into that slot or deliver a production order there. Normal mission controls cannot launch it. Only ranks granted Control permanent Alliance Fleet can withdraw personal ships, launch or recall the fleet. Alliance Ships produced by Shipyards remain locked to this fourth slot and cannot transfer to Base or personal fleets.</p><h3>Alliance Shipyards</h3><p>Owner, HC and Officer open Alliance → Shipyards to allocate hulls from current member races through a race-column quantity matrix. Unlocked hulls use the combined matching factories of current members. Costs come from Alliance Fund, above its minimum reserves; personal world discounts do not apply. Completed hulls enter the selected member’s existing Alliance Fleet, with no second fleet. Alliance sales pay the same 50% catalog rate as Ship Seller after 12 ticks and return proceeds to Alliance Fund. Cancelled sales return after a new 12-tick journey. Offline recipients receive deliveries when their game reconciles; reset or departed recipients put finished orders in escrow. Factory progress uses observed member ticks; unverified historic factory changes are not extrapolated.</p><h3>Launch Bay</h3><p>Open Alliance → Launch Bay to see your permanent fleet and prepare Attack, Defence or Fake Defence with a delay of 0–12 ticks. Existing protection, targeting and fleet availability checks still apply.</p><h3>Member readiness</h3><p>Alliance → Defence and Launch Bay show each member in an individual card. Reported idle fleets list ship names, classes and counts. Fleets travelling or scheduled are excluded. Reports refresh every 30 seconds while a member’s game is open; after five minutes they are marked stale. Missing reports remain unknown.</p><h3>Officer launch orders</h3><p>A controller can select a member’s reported fourth fleet and queue a mission. The central database checks membership and rank permissions. The member’s open game receives, validates and executes the order on its next sync; offline games wait until reopened. Revoked permissions invalidate unprocessed orders. A round reset clears reports and queued orders.</p><h3>Rank permissions</h3><p>Owner, HC and Officer receive View member idle fleets and Control permanent Alliance Fleet by default. The two permissions are separate checkboxes in Alliance → Ranks. Members, Scanners and Recruits do not receive them by default; rank permissions can explicitly delegate or revoke them.</p>']);
sections.push(['staff-controlcenters','Staff controlcenters','<h3>Admin Controlcenter</h3><p>Staff control panel → Admin Controlcenter provides a unified Round &amp; ticker workspace with one tick-interval setting and one manual-tick control, plus subpages for, Planet Editor, Stats Editor, Planet tools and Havoc. Legacy Planet Editor and Stats Editor links still open those subpages.</p><h3>Alliance Controlcenter</h3><p>Choose an alliance, then use Overview, Settings, Members, Ranks, Keyholders, Funds or Structures. Keyholders lists holder names and issuance/revocation status for staff without revealing personal keys. Settings separates name, description, recruitment message and MOTD. Members holds staff planet-to-alliance assignment and Owner-rank management. Ranks includes independent fleet-readiness and permanent-fleet-control permissions. Funds edits reserves, minimums and tax. Structures provides the advanced fortress, build queue and cooldown editor.</p><h3>Member actions</h3><p>Normal alliance pages retain actions granted to members, officers and Owners. Staff overrides are gathered in the Alliance Controlcenter. Personal Owner passkeys remain restricted to their own holder.</p><h3>Multihunters</h3><p>Raw access log and Multi are separate pages. Fleet movement review compares recorded attacks between two targets and flags patterns for staff review; it does not prove farming or automatically ban accounts. Support and Multihunter ranks can also read the separate Staff planet audit page.</p><h3>Forums &amp; achievements</h3><p>Alliance Forums is members-only; Galaxy Forum is restricted to the current galaxy. Your own topic posts and replies count toward the corresponding achievement. Private forum content is cleared by a round reset.</p>']);
const icon=category=>'<span class="theme-icon" aria-hidden="true">'+vm.runInContext('newsIcon('+JSON.stringify(category)+')',context)+'</span>';
const logo=fs.readFileSync(path.join(root,'dist/index.html'),'utf8').match(/<svg class="blackhole-logo"[\s\S]*?<\/svg>/)?.[0]||vm.runInContext('newsIcon("SYSTEM")',context);
function layout(title,body){return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' — Starfall Command</title><link rel="stylesheet" href="/portal.css?v=20261013-finished"><link rel="stylesheet" href="/ship-stats-layout.css?v=0.112.0-percent"><link rel="stylesheet" href="/submenus.css?v=0.96.0"><script src="/error-log.js"></script><link rel="stylesheet" href="/theme-fonts.css?v=0.114.0"><link rel="stylesheet" href="/astra-nexus.css?v=0.114.0"><link rel="stylesheet" href="/special-worlds.css"></head><body><header><a class="brand" href="/"><span class="theme-icon portal-logo" aria-hidden="true">'+logo+'</span><span>STARFALL COMMAND<small>GALAXY OPERATIONS</small></span></a><nav aria-label="Portal navigation"><a href="/">Portal</a><a href="/manual.html">Manual</a><a id="portalLoginLink" href="/login.html">Sign in</a></nav></header><main>'+body+'</main><footer><span id="portalUser">Commander portal</span> · Starfall Command</footer><script src="/portal.js"></script><script src="/ambient.js?v=0.97.0"></script></body></html>';}
fs.writeFileSync(path.join(root,'dist/portal.html'),layout('Game portal','<section class="hero"><span class="eyebrow">The Vesper Reach · Commander portal</span><h1>Your world.<br>Your command.</h1><p>Build a colony, lead your fleets and share intelligence across the stars. Your next operation starts here.</p><div class="actions"><a class="button" href="/game">ENTER GAME →</a><a class="button secondary" href="/manual.html">READ THE MANUAL</a></div></section><div class="cards"><article class="card">'+icon('DEVELOPMENT')+'<h2>Build your planet</h2><p>Develop resource fields, assign your workforce and research the technologies that shape your colony.</p><a href="/manual.html#economy">Economy & development →</a></article><article class="card">'+icon('FLEET')+'<h2>Command your fleets</h2><p>Choose your ship mix, prepare operations and coordinate defence with your alliance.</p><a href="/manual.html#ships">Ships & fleet operations →</a></article><article class="card">'+icon('INTELLIGENCE')+'<h2>the Miday array</h2><p>Find shared scan reports, inspect a planet’s intelligence and filter by the information you need.</p><a href="/manual.html#miday">Scanning & shared intelligence →</a></article></div>'));
fs.writeFileSync(path.join(root,'dist/login.html'),layout('Sign in','<section class="login-card"><span class="eyebrow">Commander access</span><h1 id="loginHeading">Welcome back</h1><p id="loginIntro">Sign in with your game account to enter Starfall Command.</p><form id="loginForm"><label for="username">Username</label><input id="username" name="username" autocomplete="username" maxlength="40" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" minlength="8" maxlength="128" required><button id="loginSubmit" type="submit">Sign in</button><div id="loginStatus" class="status" role="status" aria-live="polite"></div></form><p><a href="/manual.html#start">New to the game? Read the manual →</a></p></section>'));
function shadeManualSubsections(html){const tags=/<\/?([a-z0-9]+)\b[^>]*>/gi,voids=new Set(['img','br','hr','input','meta','link','source','wbr']),stack=[];let result='<div class="manual-subsection manual-introduction">',cursor=0,match,index=0;while((match=tags.exec(html))){const tag=match[1].toLowerCase(),closing=match[0].startsWith('</');result+=html.slice(cursor,match.index);if(!closing&&tag==='h3'&&stack.length===0){result+='</div><div class="manual-subsection" data-subsection="'+(++index)+'">';}result+=match[0];if(closing){const found=stack.lastIndexOf(tag);if(found>=0)stack.splice(found);}else if(!voids.has(tag)&&!match[0].endsWith('/>'))stack.push(tag);cursor=tags.lastIndex;}return result+html.slice(cursor)+'</div>';}
Object.assign(categoryIcons,{'order-drafts':'FLEET',bonuses:'ECONOMY',ticker:'SYSTEM','staff-news':'SYSTEM',races:'ALLIANCE',covert:'INTELLIGENCE'});

sections.push(['universe','Universe rankings & growth','<p>Largest planets by asteroid size and most populated planets are separate rankings. Growers and losers show observed changes in asteroids, value and population over up to 24 ticks. Negative changes retain their sign. History begins when this browser observes the round; unavailable past data is not invented.</p>']);
categoryIcons.universe='ALLIANCE';
const manualGroups=[['First steps',['start','planet-types','navigation','ticks','ticker','races']],['Develop your planet',['economy','governments','population','construction','research','order-drafts','bonuses']],['Fleet command',['ships','fleet-operations','combat','covert','attack-operations']],['Intelligence & universe',['scans','miday','galaxies','universe','politics']],['Alliance & community',['alliance','alliance-ownership','launch-bay','community-support','archive']],['Staff & reference',['staff-controlcenters','staff-news','havoc','lore']]];
sections.find(x=>x[0]==='bonuses')[2]+='<h3>Expanded quest arcs</h3><p>Every office offers at least fifteen supported goals. Achievement statistics is the summary-only landing tab; the upper navigation orders Education, Development, Habitats, Treasury, Defence, Security, Fleet, Joint Chiefs, Veterans, Intelligence, Counter Intelligence, Clandestine Services, Covert Civil Operations, Alliance Cooperation and Temporal Command. Reward treasury contains unallocated grants.</p><p>New arcs grant measured resources, CU, RP, settlers and free structures. Settlers remain in the reward reserve until housing is available. Free structures require the corresponding research unlock and a free slot; otherwise their full CU cost is credited instead. This applies to bonus construction allocation as well: locked structures cannot be bypassed with CU.</p><p>Factory warrants require Fighter I, Frigate I or Siege I for light, medium or heavy facilities. Refinery warrants require Core Mining I, Finance Centres Core II, Wave Amplifiers Scans I, Wave Distorters Scans II and Structure Defence Siege I. Biodomes and laboratories are available without an additional warrant prerequisite. Every claim includes an itemised receipt; each goal can be claimed once.</p>';
sections.find(x=>x[0]==='politics')[2]+='<h3>Spacing Bank Collective · Spaceport</h3><p>The universal exchange is a finite fund. Each round begins with 1,000,000 Metal, Crystal and Eonium by default. Staff controls resource values, minimum reserves, maximum transaction, per-player per-tick allowance and 0–25% exchange tax in Admin Controlcenter → Spacing Bank. Only admins change the starting reserves; those changes apply next round.</p><p>Gross output is the offered amount multiplied by its resource value and divided by the desired resource value, rounded down. The fee is gross output times tax, rounded down. Net output is gross minus fee. The bank receives the full offered amount and pays only net output, retaining the fee through reduced payment. A trade fails if the player lacks stock or the payment would cross a minimum reserve. Receipts and resource changes settle atomically; repeat submission of the same transaction does not pay twice.</p>';
sections.find(x=>x[0]==='construction')[2]+='<p>Construction has four slots total: one active project and up to three waiting projects. Projects may be queued while construction runs. Costs are reserved when queued; cancelling refunds the displayed eligible share once.</p>';
sections.find(x=>x[0]==='start')[2]+='<section class="command-contribution-archive"><h3>In loving memory of: 3 of 7 · Primary Unimatrix001</h3><p>Command archive · A record of repairs and additions to Starfall Command.</p>'+JSON.parse(fs.readFileSync(path.join(root,'scripts/changelog.json'),'utf8')).filter(r=>r.version.split('.').map(Number)[1]>=115).map(r=>'<details><summary>v'+esc(r.version)+' · '+esc(r.title)+'</summary><p>'+esc(r.date)+' · '+esc(r.synopsis)+'</p><ul>'+r.changes.map(change=>'<li>'+esc(change)+'</li>').join('')+'</ul></details>').join('')+'</section>';
sections.find(x=>x[0]==='planet-types')[2]+='<h3>Ancestral Thrones</h3><p>Five Ultimate player-race homeworlds have one charter each per round. Each holder receives 10% lower resource production prices for all ships, multiplied with government cost reductions before rounding up. New orders use the discount; paid orders retain their recorded cost. Confirmation applies the existing race theme, and an assignment that changes the theme reloads the interface once.</p><p>Frontier Worlds contains 20 active original environment types, all above 60% habitability. The remaining families are Stellar Heritage, Imperial Legends, Machine Worlds, Fluidic Sanctuaries, Signature Worlds and Ancestral Thrones. Internal IDs and existing reservations remain stable.</p>';
sections.find(x=>x[0]==='staff-controlcenters')[2]+='<h3>Site management test features</h3><p>The former News articles tab is Site management. It retains the news editor and adds centrally saved switches for Round history demonstration rounds and the simulated battle lab. Demonstration rounds are explicitly fictional and disappear automatically when a completed real round is archived. The normal battle calculator remains available when its separate test lab is disabled.</p><p>The public Staff personnel page and Round history are linked from the portal’s top menu. Staff information includes public account names, account IDs, roles and duties; passwords, sessions and internal audit evidence are not part of the public directory.</p>';
sections.find(x=>x[0]==='staff-controlcenters')[2]+='<h3>Account registry and personnel</h3><p>Each account has a unique five-character, read-only account ID, visible in Account profile, the planetary command card and staff personnel cards. Internal relationship keys remain intact. Staff overview lists all administrators, support officers and fair-play investigators with their duties. Staff workspaces do not require a personal planet; account role permissions still apply. Saving round settings displays an inline timestamped confirmation in the staff workspace.</p>';
const manualTitles={miday:'Satelite Uplink & shared intelligence',archive:'Journal, Achievements & troubleshooting',bonuses:'Achievement rewards & Bonuses bank',havoc:'Staff round tools & Havoc'};
const manualBodies={
 start:'<h3>Your first session</h3><ol><li>Create or sign in to a portal account and choose Continue game.</li><li>Confirm your ruler, planet, race, theme and assigned world on the colonial registration page. This repeats after each reset. Optional music and later identity settings are under Planet Settings.</li><li>Review Mining, Government, Construction and Research. Prepare your fleet worksheet before planning an operation.</li><li>Create, recover or join an alliance. The creator becomes Owner.</li><li>Read Achievements and allocate claimed rewards from the Bonuses bank.</li></ol><h3>Where to go next</h3><p>Use <a href="#economy">Resources & income</a> for development, <a href="#fleet-operations">Fleet operations</a> for missions, and <a href="#alliance-ownership">Alliance recovery</a> for saved alliance keys. A fresh or reset ticker remains stopped until manually started or newly scheduled.</p><h3>What is saved</h3><p>Accounts, memberships, shared intelligence and forum permissions are central. Practice simulation progress uses this browser. Keep the same browser when continuing a round; clocks shown in the header do not turn the simulation into a server ticker.</p>',
 navigation:'<h3>Portal</h3><p>User control panel contains Account profile, Portal theme settings, Alliance manager, Support tickets and Create account. Staff control panel offers role-restricted tools. Portal theme settings controls the portal and manual; Planet Settings controls game appearance.</p><h3>Game menu</h3><p>Military groups fleet and combat systems. Foreign Affairs opens Network Hub, Galaxy Browser, Politics, Galaxy Fund, Alliance, Mail and Universe. Archive contains Satelite Uplink, Journal, Forums, Discord and Achievements. Development shortcuts open Mining, Construction, Research, Population and Planet Settings.</p><h3>Staff navigation</h3><p>Staff tools live in the portal. Admin Controlcenter groups Round &amp; ticker, Planet Editor, Stats Editor, Planet tools and Havoc. Alliance Controlcenter has separate editors. Multihunters groups access logs, shared-IP review and fleet analysis. Staff can toggle the original game staff view from the portal.</p><h3>Finding a rule</h3><p>Choose a subject group, search for an action or use the chapter links. Search matches current chapter text. Previous and Next follow the grouped chapter order; chapter headings provide direct links.</p>',
 'alliance-ownership':'<h3>Create, reserve or recover</h3><p>Creating an alliance makes you Owner. Under User control panel → Alliance manager you can reserve up to five inactive alliances, edit your active alliance and add up to two additional keyholders. Reservations do not activate a round alliance until you choose activation.</p><h3>Recovery visibility</h3><p>Without an alliance, Restore an alliance stays available even while the ticker runs. Enter your personal Owner passkey to restore the reserved name and attributes. Once you are an alliance member, the recovery box is hidden. Funds, structures, scans and intel are not restored.</p><h3>Owner keys and passphrases</h3><p>Each Owner receives a personal encrypted key. Alliance Settings shows only your own key. An optional disclosure passphrase of 12–128 characters allows staff to reveal that specific key on the Keyholders page. Rotating the key invalidates the old key and disclosure phrase. Owner private feeds require the rights of that Owner in the active alliance.</p><h3>Rank rules</h3><p>Only an Owner or authorised staff can grant or remove Owner rank. Operational permissions are configurable in Ranks. Attack claim permissions and the one-active-claim limit apply to administrators too.</p>',
 archive:'<h3>Journal</h3><p>Journal records round events. Use its search and category filters to find battle reports, development and game updates. Calculator simulation reports stay on the calculator page; Uplink tests stay in their test module.</p><h3>Achievements</h3><p>Claiming an individual objective, a batch or automatic rewards creates an itemised Journal receipt. It lists claimed objectives, gold claim medals and exact totals for Metal, Crystal, Eonium, RP, CU and each asteroid type. Totals describe this claim only, separate from any existing balance or startup bonus.</p><p>Completed achievements offer claimable rewards. Planet Settings can enable automatic claiming. Claimed resources, asteroids, research points and construction units enter the Bonuses bank; allocate them from there. Forum achievements count your own qualifying posts.</p><h3>Help and error reports</h3><p>Open User control panel → Support tickets for staff support or a ban appeal. Only you and authorised staff see the ticket. The bottom-corner error control can expose recorded errors to include in a ticket. Describe the action, expected result and actual result.</p><h3>Related chapters</h3><p><a href="#bonuses">Bonus allocation</a> · <a href="#community-support">Forums and support</a> · <a href="#ticker">Ticker troubleshooting</a></p>'
};
manualBodies.archive+='<h3>Biodome quest line</h3><p>Completed Biodomes at 1/5/15/25/50 reward 50/150/300/500/1,000 CU and 50/100/200/350/700 research units (RU, recorded as RP). Total: 2,000 CU and 1,400 RU. Each milestone pays once, without resources or asteroid grants. A single quest uses the same festive receipt as a multi-quest claim, with exactly one achievement, medal and reward receipt.</p><h3>Civil covert quest lines</h3><p>Separate successful-worker-bribery and Biodome-sabotage lines reward at 1/5/15 operations: 100/200/400 CU and 200/400/800 RU. Failed operations do not advance these objectives.</p>';
sections.find(x=>x[0]==='havoc')[2]+='<h3>Ten-ship race matrix</h3><p>Enter ten quantities, one for each numbered ship row. The five race columns show the corresponding named ship. Apply to all gives every planet those amounts in its own race’s Base fleet, without spreading class totals across multiple types. Other fleet slots and active missions retain their ships.</p>';
sections.find(x=>x[0]==='havoc')[2]+='<h3>Confirm and saved setups</h3><p>Confirm setup validates all ten ship quantities and every target race before any game values change. A non-zero quantity without a matching racial ship blocks the entire application. Edits invalidate the confirmation. Each confirmation saves the full current Havoc form in this browser’s history; the latest five are retained, and a sixth replaces the oldest. Use Previous Havoc setups → Load setup, review, confirm and Apply to all. Loading does not alter planets.</p>';
const orderedManual=manualGroups.flatMap(([,ids])=>ids.map(id=>sections.find(x=>x[0]===id)).filter(Boolean));
const manualNav=manualGroups.map(([group,ids])=>'<div class="manual-nav-group"><h3>'+esc(group)+'</h3>'+ids.map(id=>{const entry=sections.find(x=>x[0]===id);return entry?'<a href="#'+id+'" data-manual-link="'+id+'">'+icon(categoryIcons[id])+'<span>'+esc(manualTitles[id]||entry[1])+'</span></a>':'';}).join('')+'</div>').join('');
const manualHome='<section id="manual-home" class="manual-home"><h2>Choose your next action</h2><div class="manual-topic-grid">'+manualGroups.map(([group,ids])=>'<article class="card"><h3>'+esc(group)+'</h3>'+ids.map(id=>{const entry=sections.find(x=>x[0]===id);return '<a href="#'+id+'">'+esc(manualTitles[id]||entry[1])+' →</a>';}).join('')+'</article>').join('')+'</div></section>';
const manualChapters=orderedManual.map(([id,title,body],i)=>{const content=manualBodies[id]||body;return '<section class="manual-section manual-chapter" id="'+id+'" data-chapter-title="'+esc(manualTitles[id]||title)+'"><div class="manual-chapter-meta"><span>CHAPTER '+String(i+1).padStart(2,'0')+' / '+orderedManual.length+'</span><a href="#manual-home">ALL CHAPTERS ↑</a></div><h2>'+icon(categoryIcons[id])+esc(manualTitles[id]||title)+'</h2><nav class="manual-local-links" aria-label="In this chapter">'+[...content.matchAll(/<h3>(.*?)<\/h3>/g)].map((m,n)=>'<a href="#'+id+'-part-'+n+'">'+m[1]+'</a>').join('')+'</nav>'+shadeManualSubsections(content.replace(/<h3>(.*?)<\/h3>/g,((n=0)=>(match,text)=>'<h3 id="'+id+'-part-'+n+++'">'+text+'</h3>')()))+'<nav class="manual-chapter-pager" aria-label="Chapter navigation">'+(i?'<a href="#'+orderedManual[i-1][0]+'">← '+esc(manualTitles[orderedManual[i-1][0]]||orderedManual[i-1][1])+'</a>':'<a href="#manual-home">← Manual home</a>')+(i<orderedManual.length-1?'<a href="#'+orderedManual[i+1][0]+'">'+esc(manualTitles[orderedManual[i+1][0]]||orderedManual[i+1][1])+' →</a>':'<a href="#manual-home">Manual home →</a>')+'</nav></section>';}).join('');
fs.writeFileSync(path.join(root,'dist/manual.html'),layout('Game manual','<section class="hero manual-hero"><span class="eyebrow">STARFALL · CURRENT GAME GUIDE</span><h1>Command field manual.</h1><p>Start with an action. Find the rule. Continue your command.</p><div class="actions"><a class="button" href="#start">FIRST STEPS →</a><a class="button secondary" href="/game">RETURN TO GAME →</a></div></section><div class="manual-toolbar"><div class="manual-search-wrap"><label for="manualSearch">Search all chapters</label><input id="manualSearch" class="manual-search" type="search" placeholder="Try recovery, claims, research or ticker…"><p id="manualSearchStatus" class="status" role="status" aria-live="polite">'+sections.length+' chapters</p></div><button type="button" id="manualClearSearch">CLEAR SEARCH</button><a class="button secondary" href="#manual-home">CONTENTS</a></div><div class="manual-layout manual-guide"><aside class="manual-nav" aria-label="Manual chapters"><a class="manual-home-link" href="#manual-home">MANUAL HOME</a>'+manualNav+'</aside><div class="manual-reading"><div id="manualSearchResults" hidden></div>'+manualHome+manualChapters+'</div></div>'));

let html=fs.readFileSync(path.join(root,'dist/index.html'),'utf8');if(!html.includes('data-portal-logout'))html=html.replace('<div class="local-tag">','<div class="game-portal-controls"><a class="btn" href="/">PORTAL</a><a class="btn" href="/manual.html">MANUAL</a><button class="btn" data-portal-logout>SIGN OUT</button></div><div class="local-tag">').replace('</body>','<script src="/portal.js"></script></body>').replace('</style>','.game-portal-controls{display:flex;flex-wrap:wrap;gap:5px;margin-top:12px}.game-portal-controls .btn{font-size:8px;padding:7px}</style>');fs.writeFileSync(path.join(root,'dist/index.html'),html);
console.log('Portal, login and manual built: '+sections.length+' detailed categories');
const races=['Terran','Cathaar','Xandathrii','Zikonian','Eitraides'];
const raceDescriptions={Terran:'Orbital shipyards and the fleets that reconnect the Reach.',Cathaar:'Listening arrays and precision vessels tracking distant signals.',Xandathrii:'Navigators charting the fractured jumpgate corridors.',Zikonian:'Industrial foundries forging the frontier’s warships.',Eitraides:'Ancient archives and fleets guarding the lost beacon routes.'};
const shipClasses=['Fighter','Corvette','Frigate','Destroyer','Cruiser','Battleship'];
const shipAsset=(race,cls)=>'/assets/ship-cards/'+race.toLowerCase()+'-'+cls.toLowerCase()+'.webp';
fs.writeFileSync(path.join(root,'dist/rules.html'),layout('Community & game rules','<section class="hero"><span class="eyebrow">COMMAND CODE</span><h1>Community & game rules</h1><p>Keep the Reach fair, respectful and welcoming.</p></section><div class="rules-grid">'+[['01','Respect other players','No harassment, hateful language, threats or sharing another person’s private information. Keep discussions and alliance diplomacy respectful.'],['02','Fair play','Do not exploit bugs, automate abusive actions, evade restrictions or access accounts and private intelligence without permission. Report suspected exploits privately to staff.'],['03','Accounts & passkeys','Protect your password and personal Owner passkey. Share alliance intelligence only within the permissions granted to you.'],['04','Forums & media','Keep posts relevant. No spam, impersonation or unlawful content. Cinematic AI battle clips are labelled as concepts and do not represent live combat results.'],['05','Staff support & appeals','Use User Profile → Support tickets for staff help or a ban appeal. Include the relevant dates and a clear explanation. Staff review is required; submitting an appeal does not lift a restriction automatically.'],['06','Practice rounds & resets','This site contains a practice simulation. Round resets clear gameplay data; saved identity and account access remain. The manual explains each system and its limitations.']].map(([n,t,b])=>'<article class="manual-section rule-box"><span class="rule-number">'+n+'</span><h2>'+t+'</h2><p>'+b+'</p></article>').join('')+'</div><div class="actions"><a class="button" href="/profile.html#tickets">CONTACT STAFF</a><a class="button secondary" href="/manual.html">READ THE MANUAL</a></div>'));
const picker='';fs.writeFileSync(path.join(root,'dist/forums.html'),layout('Forums','<section class="hero"><span class="eyebrow">COMMUNITY</span><h1>Forums</h1><p>Community topics and private alliance discussions.</p></section><div id="forumContent"></div><script src="/forums.js"></script>'));
const commandStrip='<div class="portal-command-strip"><span>✦ VESPER REACH</span><span>COMMAND NETWORK · ONLINE</span><a href="/game">ENTER COMMAND →</a></div>';
const releases=JSON.parse(fs.readFileSync(path.join(__dirname,'changelog.json'),'utf8')).sort((a,b)=>b.date.localeCompare(a.date)||b.version.localeCompare(a.version,undefined,{numeric:true}));
const releaseCategory=r=>/ticker|clock|time display/i.test(r.title)?'Pauzed and resumed update':/stats|metrics|fleet reference/i.test(r.title)?'Stats update':/repair|fix|reset defaults/i.test(r.title)?'Error update':/round|universe|sharing preferences/i.test(r.title)?'Round update':'Game mechanic update';
const newsPath=r=>'/news-v'+r.version.replaceAll('.','-')+(r.part?'-part-'+r.part:'')+'.html';
const releaseNews='<section class="news-module" id="news-posts"><div class="section-bar"><span>NEWS POSTS</span><a href="/news.html">NEWS ARCHIVE →</a></div><div class="cards" id="portalNewsCards">'+releases.slice(0,3).map(r=>'<article class="card" data-news-date="'+r.date+'" data-news-category="'+releaseCategory(r)+'">'+icon('SYSTEM')+'<span class="eyebrow">'+r.date+' · V'+r.version+'</span><h2>'+esc(r.title)+'</h2><p>'+esc(r.synopsis)+'</p><a href="'+newsPath(r)+'">Read the news article →</a></article>').join('')+'</div></section><section id="changelog" class="portal-changelog-module"><div class="section-bar"><span>VERSION CONTROL · RELEASE STATISTICS</span><small>COMMAND OPERATIONS LEDGER</small></div><div class="changelog-overview"><div><span>LATEST VERSION</span><strong>v'+releases[0].version+'</strong></div><div><span>RECORDED RELEASES</span><strong>'+releases.length+'</strong></div><div><span>LATEST CHANGES</span><strong>'+releases[0].changes.length+'</strong></div><svg viewBox="0 0 320 90" aria-hidden="true"><path d="M0 75H320M0 45H320M0 15H320M40 0V90M120 0V90M200 0V90M280 0V90" stroke="currentColor" opacity=".15"/><path d="M10 78 50 65 90 69 130 50 170 38 210 42 250 24 310 10" fill="none" stroke="currentColor" stroke-width="3"/></svg></div><div class="secret-reveal" tabindex="0" aria-label="Hidden transmission"><span class="secret-marker" aria-hidden="true">⌁</span><div class="secret-content"><b>CLASSIFIED · FLEET APPEARANCE</b><label><input type="checkbox" data-secret-trek> Star Trek inspired fleet</label><p>Discover the great powers and hero registries in Planet Settings.</p><a href="/game#planetSettings">OPEN THEME SETTINGS →</a></div></div><div class="changelog-release-list"><h2>Version changelog</h2>'+releases.slice(0,10).map((r,i)=>'<details '+(i===0?'open':'')+'><summary><b>v'+r.version+'</b> · '+esc(r.title)+' <time>'+r.date+'</time></summary><ul>'+r.changes.map(c=>'<li>'+esc(c)+'</li>').join('')+'</ul><a href="'+newsPath(r)+'">Full news article →</a></details>').join('')+'</div></section>';
const newsFiles=['news.html',...releases.map(r=>newsPath(r).slice(1))];
fs.writeFileSync(path.join(root,'dist/news.html'),layout('News archive','<section class="hero"><span class="eyebrow">COMMAND OPERATIONS · NEWS ARCHIVE</span><h1>Command dispatches</h1><p>Latest news first. Read the full briefing for each version.</p></section><section class="news-archive">'+releases.map(r=>'<article data-news-category="'+releaseCategory(r)+'"><time datetime="'+r.date+'">'+r.date+'</time><span class="eyebrow">V'+r.version+'</span><h2><a href="'+newsPath(r)+'">'+esc(r.title)+'</a></h2><p>'+esc(r.synopsis)+'</p><a href="'+newsPath(r)+'">Read full article →</a></article>').join('')+'</section>'));
const versionList=release=>'<article class="manual-section news-article version-article"><h2>'+icon('SYSTEM')+'Versions & code references</h2><p>Newest first. Snippets illustrate the implementation; they are references, not commands to run in the browser.</p><ol class="release-version-list">'+releases.filter(r=>r.version.localeCompare(release.version,undefined,{numeric:true})<=0).map(r=>'<li id="v'+r.version.replaceAll('.','-')+'"><header class="release-version-heading"><span class="release-version-badge">v'+r.version+'</span><time datetime="'+r.date+'">'+r.date+'</time></header><h3>'+esc(r.title)+'</h3><ul>'+r.changes.map(c=>'<li>'+esc(c)+'</li>').join('')+'</ul>'+(r.codeSnippets||[]).map(code=>'<figure class="release-code"><figcaption>Code reference · v'+r.version+'</figcaption><pre><code>'+esc(code)+'</code></pre></figure>').join('')+'<a href="'+newsPath(r)+'">Version article →</a></li>').join('')+'</ol><a class="button secondary" href="/news.html">← NEWS ARCHIVE</a></article>';
for(const r of releases)fs.writeFileSync(path.join(root,'dist',newsPath(r).slice(1)),layout(r.title,'<section class="hero"><span class="eyebrow">COMMAND DISPATCH · V'+r.version+' · '+r.date+'</span><h1>'+esc(r.title)+'</h1><p>'+esc(r.synopsis)+'</p></section>'+(r.version==='0.53.0'?versionList(r):'<article class="manual-section news-article"><h2>'+icon('SYSTEM')+'What changed</h2>'+r.changes.map(c=>'<p>'+esc(c)+'</p>').join('')+'<a class="button secondary" href="/news.html">← NEWS ARCHIVE</a></article>')));

const raceDeck='<section class="race-deck"><div class="section-bar"><span>02 · RACE COMMAND PROFILES</span><small>FIVE CIVILISATIONS · ONE REACH</small></div><div class="race-deck-grid">'+races.map(r=>'<article class="race-profile" data-profile="'+r+'"><img src="'+shipAsset(r,'Cruiser')+'" alt="'+r+' cruiser" loading="lazy"><div><span class="eyebrow">'+r.toUpperCase()+' COMMAND</span><h3>'+r+'</h3><p>'+raceDescriptions[r]+'</p><button type="button" data-preview-race="'+r+'">PREVIEW '+r.toUpperCase()+' SKIN</button><a href="/manual.html#ships">View fleet guide →</a></div></article>').join('')+'</div></section>';
